package twosum

import "testing"

func TestBasic(t *testing.T) {
	i, j := TwoSum([]int{2, 7, 11, 15}, 9)
	if i != 0 || j != 1 {
		t.Fatalf("got (%d, %d), want (0, 1)", i, j)
	}
}

func TestMiddle(t *testing.T) {
	i, j := TwoSum([]int{3, 2, 4}, 6)
	if i != 1 || j != 2 {
		t.Fatalf("got (%d, %d), want (1, 2)", i, j)
	}
}

func TestDuplicates(t *testing.T) {
	i, j := TwoSum([]int{3, 3}, 6)
	if i != 0 || j != 1 {
		t.Fatalf("got (%d, %d), want (0, 1)", i, j)
	}
}

func TestNegatives(t *testing.T) {
	i, j := TwoSum([]int{-3, 4, 3, 90}, 0)
	if i != 0 || j != 2 {
		t.Fatalf("got (%d, %d), want (0, 2)", i, j)
	}
}

func TestLastTwo(t *testing.T) {
	i, j := TwoSum([]int{1, 5, 8, 13, 21}, 34)
	if i != 3 || j != 4 {
		t.Fatalf("got (%d, %d), want (3, 4)", i, j)
	}
}
